import time
class Breaker:
    def __init__(self, limit=3, cool=0.2):
        self.fail, self.limit, self.cool, self.opened = 0, limit, cool, None
    def call(self, fn):
        if self.opened and time.time() - self.opened < self.cool:
            return "차단: 바로 대체 응답"
        try:
            r = fn(); self.fail, self.opened = 0, None; return r
        except Exception:
            self.fail += 1
            if self.fail >= self.limit: self.opened = time.time()
            return "실패: 대체 응답"
def partner_down(): raise TimeoutError()
b = Breaker()
for i in range(5): print(i+1, b.call(partner_down))
time.sleep(0.25)
print(6, b.call(lambda: "정상 응답"))

# 1 실패: 대체 응답
# 2 실패: 대체 응답
# 3 실패: 대체 응답
# 4 차단: 바로 대체 응답
# 5 차단: 바로 대체 응답
# 6 정상 응답
